pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/IERC721Metadata.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/IERC721Enumerable.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts/utils/Counters.sol";

interface IERC2981 {
    function royaltyInfo(uint256 _tokenId, uint256 _salePrice) external view returns (address receiver, uint256 royaltyAmount);
}

contract WhitelistMintNFT is Ownable, ERC721, IERC721Metadata, IERC721Enumerable, IERC2981 {
    using Strings for uint256;
    using Counters for Counters.Counter;

    Counters.Counter private _tokenIds;

    string public baseURI;
    string public hiddenMetadataUri;
    bool public isRevealed = false;

    mapping(address => bool) public whitelistedAddresses;
    uint256 public mintPrice;
    uint256 public maxMintAmountPerWallet;
    uint256 public maxSupply;

    uint256 private _royaltyFeeNumerator = 1000; // 1% of each sale goes to the creator (default)

    constructor(string memory baseURI_, string memory hiddenMetadataUri_) ERC721("WhitelistMintNFT", "WLM") {
        _tokenIds._value = 0;
        baseURI = baseURI_;
        hiddenMetadataUri = hiddenMetadataUri_;
    }

    function setRoyaltyFee(uint256 royaltyFee) public onlyOwner() {
        require(royaltyFee <= 1000, "Royalty fee must be less than or equal to 10%");
        _royaltyFeeNumerator = royaltyFee;
    }

    function setMintPriceAndMaxMintAmountPerWallet(uint256 price, uint256 maxMintAmount) public onlyOwner() {
        mintPrice = price;
        maxMintAmountPerWallet = maxMintAmount;
    }

    function whitelistAddress(address addr) public onlyOwner() {
        require(!whitelistedAddresses[addr], "Address already whitelisted");
        whitelistedAddresses[addr] = true;
    }

    function mint(uint256 amount) public payable {
        require(_tokenIds.current() + amount <= maxSupply, "Exceeded maximum supply");
        require(whitelistedAddresses[_msgSender()], "Not whitelisted");
        require(msg.value == amount * mintPrice, "Insufficient payment");
        for (uint256 i = 0; i < amount; ++i) {
            _safeMint(_msgSender(), _tokenIds.current());
            _tokenIds.increment();
        }
    }

    function reveal() public onlyOwner() {
        isRevealed = true;
    }

    function _baseURI() internal view override returns (string memory) {
        return baseURI;
    }

    function tokenURI(uint256 _tokenId) public view override returns (string memory) {
        require(_exists(_tokenId), "Token does not exist");
        if (!isRevealed || !_isApprovedOrOwner(_msgSender(), _tokenId)) return hiddenMetadataUri;
        return super.tokenURI(_tokenId);
    }

    function royaltyInfo(uint256 _tokenId, uint256 _salePrice) external view override returns (address receiver, uint256 royaltyAmount) {
        require(_exists(_tokenId), "Token does not exist");
        address creator = ownerOf(_tokenId);
        return (creator, (_salePrice * _royaltyFeeNumerator) / 10000);
    }
}

