pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract LiquidStaking is Ownable {
    using SafeMath for uint;

    IERC20 public stakeToken;
    ERC20 public stToken;

    constructor(IERC20 _stakeToken, address _stTokenAddress) {
        stakeToken = _stakeToken;
        stToken = ERC20(_stTokenAddress);
    }

    function stake(uint amount) external {
        require(amount > 0, "Amount must be greater than zero");
        stakeToken.transferFrom(msg.sender, address(this), amount);
        mintStTokens(msg.sender, amount);
    }

    function unstake(uint amount) external {
        require(amount > 0, "Amount must be greater than zero");
        stToken.burn(msg.sender, amount);
        stakeToken.transfer(msg.sender, amount);
    }

    function mintStTokens(address to, uint amount) internal {
        stToken.mint(to, amount);
    }
}

