pragma solidity ^0.8.0;

contract ConstantProductAMM {
    uint public token0Balance;
    uint public token1Balance;
    uint public constantProduct;

    constructor() {
        token0Balance = 1 ether; // Initial liquidity
        token1Balance = 2 ether; // Initial liquidity
        constantProduct = token0Balance * token1Balance;
    }

    function swap(uint amount, bool isToken0) external {
        require(isToken0 ? msg.sender.balance >= amount : token0Balance >= amount, "Insufficient balance");

        if (isToken0) {
            uint tokensBought = constantProduct / (token0Balance + amount);
            require(tokensBought > 0, "Swap resulted in zero output");

            msg.sender.transfer(amount);
            token0Balance += amount;
            token1Balance -= tokensBought;
        } else {
            uint tokensSold = constantProduct / (token1Balance - amount);
            require(tokensSold > 0, "Swap resulted in zero output");

            payable(msg.sender).transfer(tokensSold);
            token0Balance -= tokensSold;
            token1Balance += amount;
        }
    }

    function addLiquidity(uint amountToken0, uint amountToken1) external {
        require(amountToken0 > 0 && amountToken1 > 0, "Amounts must be greater than zero");
        require((token0Balance * amountToken1) / (token0Balance + amountToken0) <= token1Balance, "Unbalanced liquidity addition");

        msg.sender.transfer(amountToken0);
        payable(msg.sender).transfer(amountToken1);
        token0Balance += amountToken0;
        token1Balance += amountToken1;
    }
}

