interface IYieldStrategy {
    function deposit(address _from, uint256 _amount) external returns (uint256);
    function withdraw(address _to, uint256 _amount) external returns (uint256);
}

contract YieldAggregatorVault {
    IYieldStrategy public yieldStrategy;
    uint256 public depositFee = 1; // 1% deposit fee
    uint256 public withdrawalFee = 2; // 2% withdrawal fee

    constructor(IYieldStrategy _yieldStrategy) {
        yieldStrategy = _yieldStrategy;
    }

    function deposit(uint256 _amount) external returns (uint256) {
        require(_amount > 0, "Amount must be greater than zero");
        uint256 feeAmount = (_amount * depositFee) / 100;
        yieldStrategy.deposit(msg.sender, _amount - feeAmount);
        return _amount - feeAmount;
    }

    function withdraw(uint256 _amount) external returns (uint256) {
        require(_amount > 0, "Amount must be greater than zero");
        uint256 feeAmount = (_amount * withdrawalFee) / 100;
        return yieldStrategy.withdraw(msg.sender, _amount - feeAmount);
    }
}

