pragma solidity ^0.8.17;

contract SocialRecoveryWallet {
    address payable public owner;
    mapping(address => bool) public guardians;
    uint256 public numGuardians;
    uint256 public recoveryThreshold;
    mapping(address => bool) public approvedTransactions;
    uint256 public transactionCount;

    constructor(uint256 _recoveryThreshold, address[] memory _guardians) {
        owner = payable(msg.sender);
        numGuardians = _guardians.length;
        recoveryThreshold = _recoveryThreshold;

        for (uint256 i = 0; i < numGuardians; i++) {
            guardians[_guardians[i]] = true;
        }
    }

    function addGuardian(address _newGuardian) public onlyOwner {
        if (!guardians[_newGuardian]) {
            guardians[_newGuardian] = true;
            numGuardians++;
        }
    }

    function removeGuardian(address _oldGuardian) public onlyOwner {
        if (guardians[_oldGuardian]) {
            delete guardians[_oldGuardian];
            numGuardians--;
        }
    }

    modifier onlyGuardian() {
        require(guardians[msg.sender], "Only guardians can execute this function.");
        _;
    }

    modifier onlyOwner() {
        require(owner == msg.sender, "Only the owner can execute this function.");
        _;
    }

    function approveTransaction(address _to, uint256 _amount) public onlyGuardian {
        if (transactionCount < recoveryThreshold) {
            approvedTransactions[msg.sender] = true;
            transactionCount++;
        } else {
            transferFunds(_to, _amount);
        }
    }

    function recoverWallet(address payable _newOwner) public {
        require(transactionCount >= recoveryThreshold, "Recovery threshold not reached.");
        owner = _newOwner;
        transactionCount = 0;
        approvedTransactions = mapping(address => bool);
    }

    function transferFunds(address payable _to, uint256 _amount) private {
        require(_amount <= address(this).balance, "Insufficient funds.");
        _to.transfer(_amount);
        transactionCount = 0;
        approvedTransactions = mapping(address => bool);
    }
}
